### RECURSION ###

# Please complete the function to recursively compute 
# whether the binary tree is symmetric 
# (i.e., the left subtree is a mirror-image of the right subtree)
# Parameters: root - TreeNode object of root node with fields: root.left, 
#       5                                                      root.right, 
#     3    3                                                   root.val
#    2  1 1  2
def is_symmetric(root) -> bool:
        
    # Base case
	if not root.left and not root.right:
        return True
	if root.left and not root.right:
        return False
    if root.right and not root.left:
        return False
    if root.left != root.right:
        return False
    # Active flowqq
    return is_symmetric(root.left) and is_symmetric(root.right)
